def generateAbbreviations(word: str) -> list[str]:
    res = []
    def backtrack(idx, curr, count):
        if idx == len(word):
            res.append(curr + (str(count) if count > 0 else ''))
            return
        # Option 1: abbreviate word[idx]
        backtrack(idx + 1, curr, count + 1)
        # Option 2: keep word[idx]
        backtrack(idx + 1, curr + (str(count) if count > 0 else '') + word[idx], 0)
    backtrack(0, '', 0)
    return sorted(res)

